import{_ as a,c as p,o as i,ah as n}from"./chunks/framework.PvdZnrZd.js";const c=JSON.parse('{"title":"Japanese shipping","description":"Japanese shipping","frontmatter":{"title":"Japanese shipping","description":"Japanese shipping","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/featured-app/shipping/japanese-shipping.md","filePath":"zenith/featured-app/shipping/japanese-shipping.md"}'),t={name:"zenith/featured-app/shipping/japanese-shipping.md"};function l(r,e,o,s,h,g){return i(),p("div",null,[...e[0]||(e[0]=[n('<h2 id="japanese-shipping-multi-vendor-marketplace-for-shopify" tabindex="-1">Japanese Shipping: Multi-vendor Marketplace for Shopify <a class="header-anchor" href="#japanese-shipping-multi-vendor-marketplace-for-shopify" aria-label="Permalink to &quot;Japanese Shipping: Multi-vendor Marketplace for Shopify&quot;">​</a></h2><p>We are delighted to announce a new Japanese Shipping feature in our Multivendor Marketplace App . Now, sellers can easily manage shipping and generate shipping labels directly from their seller panel.</p><p>This feature is specially designed for merchants operating in Japan and includes integration with three major Japanese shipping carriers:</p><ul><li>Yamato Transport</li><li>Sagawa Express</li><li>Japan Post (Yu-Pack)</li></ul><h2 id="key-benefits" tabindex="-1">Key Benefits <a class="header-anchor" href="#key-benefits" aria-label="Permalink to &quot;Key Benefits&quot;">​</a></h2><ul><li>Easy shipping management for Japanese sellers</li><li>Direct shipping label generation</li><li>Integrated tracking details</li></ul><h2 id="admin-configuration" tabindex="-1">Admin Configuration <a class="header-anchor" href="#admin-configuration" aria-label="Permalink to &quot;Admin Configuration&quot;">​</a></h2><p>To enable Japanese Shipping, the admin needs to follow the steps below:</p><h3 id="step-1-enable-feature-app" tabindex="-1">Step 1: Enable Feature App <a class="header-anchor" href="#step-1-enable-feature-app" aria-label="Permalink to &quot;Step 1: Enable Feature App&quot;">​</a></h3><p>Navigate to:<br> Marketplace Admin Panel → Feature App → Enable Japanese Shipping</p><p>Once enabled, proceed to the next configuration.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/fdgrgrefeqr.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/fdgrgrefeqr.webp" alt="image"></a></p><h3 id="step-2-enable-shipping-method" tabindex="-1">Step 2: Enable Shipping Method <a class="header-anchor" href="#step-2-enable-shipping-method" aria-label="Permalink to &quot;Step 2: Enable Shipping Method&quot;">​</a></h3><p>Go to:<br> Configuration → Shipping Method</p><p>Here, the admin must:</p><ul><li>Enable Japanese Shipping</li></ul><p>After enabling, options to activate the three shipping carriers will appear:</p><ul><li>Yamato Transport</li><li>Sagawa Express</li><li>Yu-Pack (Japan Post)</li></ul><p>The admin can enable the required carriers from here.</p><p><strong>Note:</strong> The carrier options will only appear after Japanese Shipping is enabled.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/erfefqefqfe.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/erfefqefqfe.webp" alt="image"></a></p><h2 id="seller-end-configuration" tabindex="-1">Seller End Configuration <a class="header-anchor" href="#seller-end-configuration" aria-label="Permalink to &quot;Seller End Configuration&quot;">​</a></h2><p>Once the admin enables Japanese Shipping, sellers can configure it from their panel.</p><h3 id="step-1-enable-japanese-shipping-seller-panel" tabindex="-1">Step 1: Enable Japanese Shipping (Seller Panel) <a class="header-anchor" href="#step-1-enable-japanese-shipping-seller-panel" aria-label="Permalink to &quot;Step 1: Enable Japanese Shipping (Seller Panel)&quot;">​</a></h3><p>Navigate to:<br> Seller Panel → Configuration → Shipping Method</p><p>Here, sellers will see Japanese Shipping Method.<br> They need to enable it and select the carriers they want to use (from those enabled by the admin).</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/efqrefqefgrqre.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/efqrefqefgrqre.webp" alt="image"></a></p><h3 id="step-2-create-shipping-label-data" tabindex="-1">Step 2: Create Shipping Label Data <a class="header-anchor" href="#step-2-create-shipping-label-data" aria-label="Permalink to &quot;Step 2: Create Shipping Label Data&quot;">​</a></h3><p>After enabling the shipping method:</p><ul><li>Go to My Account</li><li>Click on Create Shipping Label Data for Japanese Shipping</li><li>A pop-up will appear</li><li>Seller can select the shipping method from the enabled carriers</li><li>Configure and save the shipping details</li></ul><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/erqgqgerq.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/erqgqgerq.webp" alt="image"></a></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/erqgfqegeqgq.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/erqgfqegeqgq.webp" alt="image"></a></p><h3 id="step-3-generate-shipping-label-from-order" tabindex="-1">Step 3: Generate Shipping Label from Order <a class="header-anchor" href="#step-3-generate-shipping-label-from-order" aria-label="Permalink to &quot;Step 3: Generate Shipping Label from Order&quot;">​</a></h3><ul><li>Go to Orders</li><li>Click on View Order</li><li>Click on Create Shipping Label Data</li></ul><p>The system will generate a CSV file.</p><p>The CSV file includes:</p><ul><li>Tracking Number</li><li>Tracking URL</li><li>Shipment Details</li><li>Complete Carrier Information</li></ul><p>Once the shipment is completed successfully, the order status will automatically update to Shipped.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/egreqrgeqgqerg.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/egreqrgeqgqerg.webp" alt="image"></a></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/ergwergerg.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/02/ergwergerg.webp" alt="image"></a></p>',40)])])}const b=a(t,[["render",l]]);export{c as __pageData,b as default};
